// Hands the page's ad slots to the ad tag once the page has hydrated.
export function registerCommercialSlots(config) {
    if (!config?.adtag)
        return;
    const slots = [...document.querySelectorAll("[data-commercial-slot]")].map((element) => element.dataset.commercialSlot);
    window.adtag = window.adtag || { cmd: [] };
    window.adtag.cmd.push(() => {
        window.adtag.configure(config.adtag);
        window.adtag.registerSlots(slots);
        window.adtag.start();
    });
}
