import { createContext, useContext, useMemo } from "react";

const PageContext = createContext(null);
const StageContext = createContext(null);
const GroupContext = createContext(null);
const TrackingScopeContext = createContext("page");
const ClockContext = createContext(0);
const ThemeContext = createContext("light");
const CommercialContext = createContext(null);
const HeadingLevelContext = createContext(2);

export function PageProvider({ page, children }) {
    return <PageContext.Provider value={page}>{children}</PageContext.Provider>;
}

export function usePage() {
    return useContext(PageContext);
}

export function StageProvider({ stage, children }) {
    return (
        <StageContext.Provider value={stage}>
            <TrackingScopeContext.Provider value={stage.trackingName}>{children}</TrackingScopeContext.Provider>
        </StageContext.Provider>
    );
}

export function useStage() {
    return useContext(StageContext);
}

export function GroupProvider({ group, children }) {
    const scope = useContext(TrackingScopeContext);
    const value = useMemo(() => ({ ...group, scope: `${scope}/${group.trackingName ?? group.index}` }), [group, scope]);
    return <GroupContext.Provider value={value}>{children}</GroupContext.Provider>;
}

export function useGroup() {
    return useContext(GroupContext);
}

export function useTrackingScope() {
    return useContext(TrackingScopeContext);
}

export function ClockProvider({ now, children }) {
    return <ClockContext.Provider value={now}>{children}</ClockContext.Provider>;
}

export function useNow() {
    return useContext(ClockContext);
}

export function ThemeProvider({ theme, children }) {
    return <ThemeContext.Provider value={theme}>{children}</ThemeContext.Provider>;
}

export function useTheme() {
    return useContext(ThemeContext);
}

export function CommercialProvider({ config, children }) {
    return <CommercialContext.Provider value={config}>{children}</CommercialContext.Provider>;
}

export function useCommercial() {
    return useContext(CommercialContext);
}

export function HeadingLevel({ level, children }) {
    return <HeadingLevelContext.Provider value={level}>{children}</HeadingLevelContext.Provider>;
}

export function useHeadingLevel() {
    return useContext(HeadingLevelContext);
}
