// The site's own tracking layer: one IntersectionObserver for teaser
// impressions and one delegated click listener. Events are batched and
// serialized for a beacon that goes nowhere.
const queue = [];
let flushScheduled = false;
let sent = 0;

function sink(payload) {
    sent += payload.length;
}

function scheduleFlush() {
    if (flushScheduled)
        return;
    flushScheduled = true;
    const flush = () => {
        flushScheduled = false;
        if (queue.length)
            sink(JSON.stringify({ v: 2, page: document.documentElement.dataset.pageType, events: queue.splice(0) }));
    };
    const portal = window.__portal;
    if (portal?.hosted)
        portal.track(new Promise((resolve) => portal.afterTask(() => resolve(flush()))));
    else
        requestIdleCallback(flush, { timeout: 2000 });
}

function parseTracking(value) {
    const [region, position, id, layout] = (value ?? "").split("|");
    return { region, position, id, layout };
}

function onClick(event) {
    const target = event.target.closest?.("[data-tracking]");
    if (!target)
        return;
    const teaser = target.closest("article[data-tracking]");
    queue.push({
        type: "click",
        element: target.getAttribute("data-interaction-element") ?? target.localName,
        ...parseTracking(target.getAttribute("data-tracking")),
        teaser: teaser ? teaser.getAttribute("data-sctrack") : null,
        label: target.getAttribute("aria-label") ?? undefined,
        t: Math.round(performance.now()),
    });
    scheduleFlush();
}

let observer = null;

function onImpressions(entries) {
    for (const entry of entries) {
        if (!entry.isIntersecting)
            continue;
        observer.unobserve(entry.target);
        queue.push({ type: "impression", ...parseTracking(entry.target.getAttribute("data-tracking")), ratio: Math.round(entry.intersectionRatio * 100) });
    }
    if (queue.length)
        scheduleFlush();
}

export function startTracker() {
    document.addEventListener("click", onClick, { capture: true });
    observer = new IntersectionObserver(onImpressions, { threshold: 0.5 });
    for (const teaser of document.querySelectorAll("article[data-tracking]"))
        observer.observe(teaser);
    queue.push({ type: "pageview", path: location.pathname, referrer: document.referrer || null, bucket: window.abBucket });
    scheduleFlush();
    return () => {
        document.removeEventListener("click", onClick, { capture: true });
        observer.disconnect();
    };
}

export function trackerStats() {
    return { sent };
}
